ssize_t write(int fd, const void* buf, size_t count);
// Causes switch from User Mode to Kernel Mode (Ring 3 -> Ring 0)
// Uses interrupt 0x80 (legacy) or SYSCALL instruction (modern x86)
ssize_t bytes_written = write(1, "Hello", 5);

// The hardware pushes state onto the kernel stack
// (Used for restoration upon return/iret)
struct trap_frame {
    uint64_t rdi, rsi, rdx, r10, r8, r9; // Syscall arguments
    uint64_t rip;    // Return address
    uint64_t cs;     // Code Segment
    uint64_t rflags; // CPU Flags
    uint64_t rsp;
    uint64_t ss;     // Stack Segment
};

// Kernel: Interrupt Descriptor Table (IDT) entry structure
struct idt_entry {
    uint16_t handler_offset_low;
    uint16_t code_selector;
    uint8_t  ist_index;
    uint8_t  type_attr; // Gate Type (Interrupt, Trap, Task) & DPL
    uint16_t handler_offset_mid;
    uint32_t handler_offset_high;
    uint32_t reserved;
};

// ECF mechanism (Interrupt/Trap)
// CPU reads IDT[vector_num] -> Jumps to Handler Address (RIP)
void syscall_handler(struct trap_frame* tf) {
    uint64_t num = tf->rdi;
    // ... lookup function based on num
}
